package com.smartchat.dto;

import jakarta.validation.constraints.NotBlank;
import java.util.ArrayList;
import java.util.List;

public class ChatRequest {

    @NotBlank(message = "Prompt cannot be empty")
    private String prompt;

    /**
     * Previous conversation messages for multi-turn conversational context.
     */
    private List<ChatMessageDto> history = new ArrayList<>();

    /**
     * Unique conversation identifier (UUID or timestamp generated by client).
     */
    private String conversationId;

    public ChatRequest() {
    }

    public ChatRequest(String prompt) {
        this.prompt = prompt;
    }

    public ChatRequest(String prompt, List<ChatMessageDto> history, String conversationId) {
        this.prompt = prompt;
        this.history = history != null ? history : new ArrayList<>();
        this.conversationId = conversationId;
    }

    public String getPrompt() {
        return prompt;
    }

    public void setPrompt(String prompt) {
        this.prompt = prompt;
    }

    public List<ChatMessageDto> getHistory() {
        return history;
    }

    public void setHistory(List<ChatMessageDto> history) {
        this.history = history != null ? history : new ArrayList<>();
    }

    public String getConversationId() {
        return conversationId;
    }

    public void setConversationId(String conversationId) {
        this.conversationId = conversationId;
    }
}

